INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(22301, 'Matthew 9:37', 'Matthew', 9, 37, '&nbsp;بيا هغۀ خپلو مريدانو ته وفرمائيل چې، ”فصل ډېر دے خو مزدوران لږ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22302, 'Matthew 9:38', 'Matthew', 9, 38, '&nbsp;د دې دپاره تاسو د فصل مالِک ته خواست وکړئ چې هغه د فصل رېبلو دپاره مزدوران راولېږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22303, 'Matthew 10:1', 'Matthew', 10, 1, '&nbsp;بيا عيسىٰ خپل دولس مريدان راوغوښتل او هغوئ له يې د پيريانو شړلو او د هر قِسم بيماريانو او مرضونو شفا اختيار ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22304, 'Matthew 10:2', 'Matthew', 10, 2, '&nbsp;د هغه دولسو مريدانو نومونه دا دى، اول شمعون چې پطروس ورته وائى او د هغۀ ورور اندرياس، د زبدى زوئ يعقوب او د هغۀ ورور يوحنا،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22305, 'Matthew 10:3', 'Matthew', 10, 3, '&nbsp;فيليپوس او برتلماۍ، توما او متى محصولچى، د حلفى زوئ يعقوب او تدى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22306, 'Matthew 10:4', 'Matthew', 10, 4, '&nbsp;شمعون ننګيالے او يهوداه اِسکريوتى، يعنې هغه سړے چې په عيسىٰ يې جاسوسى وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22307, 'Matthew 10:5', 'Matthew', 10, 5, '&nbsp;عيسىٰ دا دولس کسان د دې هداياتو سره ولېږل چې، ”د غېر يهودى قومونو په طرف مۀ ځئ او د سامريانو ښار ته مۀ ننوځئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22308, 'Matthew 10:6', 'Matthew', 10, 6, '&nbsp;خو د هغې په ځائ د بنى اِسرائيلو د خاندان ورکو شوو ګډو له لاړ شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22309, 'Matthew 10:7', 'Matthew', 10, 7, '&nbsp;او په تلو تلو کښې دا پېغام ورکوئ چې د آسمان بادشاهى رانزدې شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22310, 'Matthew 10:8', 'Matthew', 10, 8, '&nbsp;بيماران جوړَوئ، مړى ژوندى کوئ، جذاميان پاکوئ او پيريان شړئ. تاسو ته دا اختيار مفت درکړے شو او مفت يې ورکوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22311, 'Matthew 10:9', 'Matthew', 10, 9, '&nbsp;سرۀ زر يا سپين زر يا تانبه په خپلې تيلۍ کښې مۀ اخلئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22312, 'Matthew 10:10', 'Matthew', 10, 10, '&nbsp;د ځان سره نۀ د سفر تيلۍ، نۀ دوېم قميص، نۀ اضافى پېزار او مۀ امسا اخلئ، ځکه چې مزدور د خپلې مزدورۍ حقدار دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22313, 'Matthew 10:11', 'Matthew', 10, 11, '&nbsp;کوم ښار يا کلى ته چې تاسو ننوځئ نو د داسې يو عزتمند سړى کور ته ورځئ چې د ورتلو قابل وى، او هلته پاتې شئ تر هغې چې د هغه ځايه بل ځائ ته رُخصت شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22314, 'Matthew 10:12', 'Matthew', 10, 12, '&nbsp;کوم کور ته چې تاسو ننوځئ، د هغوئ سلامتى غواړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22315, 'Matthew 10:13', 'Matthew', 10, 13, '&nbsp;کۀ هغه د دې لائق وى نو ستاسو سلامتى به ورورسيږى، او کۀ لائق نۀ وى نو ستاسو سلامتى به واپس تاسو ته راوګرځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22316, 'Matthew 10:14', 'Matthew', 10, 14, '&nbsp;خو کۀ چرې څوک تاسو قبول نۀ کړى او غوږ درته ونۀ نيسى نو چې کله تاسو هغه کور يا ښار پرېږدئ نو د خپلو پښو نه دوړې وڅنډئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22317, 'Matthew 10:15', 'Matthew', 10, 15, '&nbsp;زۀ تاسو ته رښتيا وايم چې په ورځ د قيامت به د سدوم او د عموره د خلقو حال د دې ښار د خلقو د حال نه ښۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22318, 'Matthew 10:16', 'Matthew', 10, 16, '&nbsp;ګورئ، زۀ تاسو لکه د ګډو په شان د شرمخانو مينځ ته لېږم. د مارانو په شان هوښيار او د کونترو په شان بې‌آزاره اوسئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22319, 'Matthew 10:17', 'Matthew', 10, 17, '&nbsp;خبردار اوسئ چې دوئ به تاسو عدالتونو ته حواله کوى او په خپلو عبادتخانو کښې به مو په کوړو وهى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22320, 'Matthew 10:18', 'Matthew', 10, 18, '&nbsp;او زما د خاطره به تاسو حاکمانو او بادشاهانو ته وړاندې کوى چې د هغوئ او غېر‌يهوديانو دپاره ګواهان شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22321, 'Matthew 10:19', 'Matthew', 10, 19, '&nbsp;خو هر کله چې تاسو ونيولے شئ نو د دې سوچ مۀ کوئ چې تاسو به څۀ او څنګه ووايئ. چې وخت راشى نو هغه خبرې به په خپله ستاسو خولې ته راشى چې تاسو ته يې ضرورت وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22322, 'Matthew 10:20', 'Matthew', 10, 20, '&nbsp;ځکه کومې خبرې چې تاسو کوئ دغه به تاسو په خپله نۀ کوئ، خو ستاسو په ذريعه به ستاسو د آسمانى پلار روح خبرې کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22323, 'Matthew 10:21', 'Matthew', 10, 21, '&nbsp;ورور به د ورور د مرګ جاسوس شى او پلار به د زوئ، او اولاد به د مور پلار خلاف شى او مرګ ته به يې حواله کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22324, 'Matthew 10:22', 'Matthew', 10, 22, '&nbsp;ټول به زما د نوم په سبب تاسو سره کينه کوى خو هغه څوک چې تر آخره قائم پاتې شى هغه به بچ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22325, 'Matthew 10:23', 'Matthew', 10, 23, '&nbsp;کله چې تاسو په يو ښار کښې وزورولے شئ نو بل ته لاړ شئ. زۀ درته رښتيا وايم چې د دې نه وړاندې چې تاسو د بنى اِسرائيلو په ټولو ښارونو کښې وګرځئ نو اِبن آدم به واپس راشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22326, 'Matthew 10:24', 'Matthew', 10, 24, '&nbsp;شاګرد د خپل اُستاذ نه لوئ نۀ وى او نۀ نوکر د خپل مالِک نه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22327, 'Matthew 10:25', 'Matthew', 10, 25, '&nbsp;د شاګرد دپاره دا کافى ده چې د اُستاذ په شان شى او نوکر د خپل مالِک په شان. کۀ د يو کور مالِک ته بعلزبول وئيلے شى نو د هغۀ د کور کسان به د دې نه هم په خراب نوم ياد کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22328, 'Matthew 10:26', 'Matthew', 10, 26, '&nbsp;نو د هغوئ نه يره مۀ کوئ ځکه چې داسې پټ څيز نشته چې ښکاره به نۀ شى، او نۀ داسې پټ راز شته چې هغه به ښکاره نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22329, 'Matthew 10:27', 'Matthew', 10, 27, '&nbsp;څۀ چې زۀ تاسو ته په تيارۀ کښې وايم نو تاسو يې په رڼا کښې وايئ. څۀ چې تاسو ته په غوږ کښې ووئيلے شى هغه تاسو د چت دپاسه په چغو وايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22330, 'Matthew 10:28', 'Matthew', 10, 28, '&nbsp;د هغه چا نه مۀ يرېږئ څوک چې وجود وژنى خو روح نۀ شى وژلے، خو د هغه چا نه يرېږئ څوک چې روح او بدن دواړه په دوزخ کښې بربادولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22331, 'Matthew 10:29', 'Matthew', 10, 29, '&nbsp;ولې دوه چڼچڼې په يوه پېسه نۀ خرڅيږى څۀ؟ خو بيا هم ستاسو د پلار د رضا نه بغېر يوه هم په زمکه نۀ راپرېوځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22332, 'Matthew 10:30', 'Matthew', 10, 30, '&nbsp;خو دا چې ستاسو د سر ټول وېښتۀ هم شمېرلے شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22333, 'Matthew 10:31', 'Matthew', 10, 31, '&nbsp;نو بيا مۀ يرېږئ، تاسو د بې‌شمېره چڼچڼو نه زيات قيمتى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22334, 'Matthew 10:32', 'Matthew', 10, 32, '&nbsp;هر څوک چې د خلقو په وړاندې زما اِقرار وکړى، زۀ به په آسمان کښې د خپل پلار په وړاندې د هغۀ اِقرار وکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22335, 'Matthew 10:33', 'Matthew', 10, 33, '&nbsp;خو هر څوک چې د خلقو په وړاندې زما نه اِنکار وکړى، زۀ به په آسمان کښې د خپل پلار په وړاندې د هغۀ نه اِنکار وکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22336, 'Matthew 10:34', 'Matthew', 10, 34, '&nbsp;تاسو دا خيال مۀ کوئ چې زۀ ګنې دُنيا ته د امن راوستو دپاره راغلے يم. نه، زۀ د امن راوستو دپاره نه، خو د جنګ دپاره راغلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22337, 'Matthew 10:35', 'Matthew', 10, 35, '&nbsp;زۀ دې له راغلے يم چې سړے د خپل پلار خلاف شى، لور د مور، او اِنږور د خواښې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22338, 'Matthew 10:36', 'Matthew', 10, 36, '&nbsp;او د سړى دشمنان به د هغۀ د کور خلق وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22339, 'Matthew 10:37', 'Matthew', 10, 37, '&nbsp;داسې کس زما قابل نۀ دے چې د خپل مور پلار سره زما نه زياته مينه کوى او هغه څوک هم چې زما نه زياته مينه د خپل زوئ يا لور سره کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22340, 'Matthew 10:38', 'Matthew', 10, 38, '&nbsp;داسې خلق زما جوګه نۀ دى څوک چې خپله سولۍ نۀ پورته کوى او زما په نقش قدم نۀ ځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22341, 'Matthew 10:39', 'Matthew', 10, 39, '&nbsp;څوک چې خپل ځان ساتل غواړى هغه به يې بائيلى، خو څوک چې زما د خاطره خپل ژوند بائيلى، هغه به يې حاصل کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22342, 'Matthew 10:40', 'Matthew', 10, 40, '&nbsp;څوک چې تاسو قبلوى هغه ما قبلوى او څوک چې ما قبلوى نو هغه هغه څوک قبلوى چې زۀ يې رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22343, 'Matthew 10:41', 'Matthew', 10, 41, '&nbsp;هر هغه څوک چې يو نبى د نبى په نوم قبلوى هغۀ ته به د نبى اجر ملاويږى، او هر هغه څوک چې يو صادق د صادق په نوم قبلوى، هغۀ ته به د صادق اجر ملاويږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22344, 'Matthew 10:42', 'Matthew', 10, 42, '&nbsp;هر هغه څوک کۀ يو جام يخې اوبۀ دې ورکوټى له په دې وجه ورکړى چې هغه زما مريد دے، نو زۀ درته دا وايم چې هغه کس به بې‌اجره پاتې نۀ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22345, 'Matthew 11:1', 'Matthew', 11, 1, '&nbsp;کله چې عيسىٰ خپلو دولسو مريدانو ته هدايت ورکول ختم کړل نو بيا هغه د هغه ځائ نه روان شو چې د هغوئ په ښارونو کښې تعليم ورکړى او بيان وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22346, 'Matthew 11:2', 'Matthew', 11, 2, '&nbsp;کله چې يحيىٰ بپتسمه ورکوونکے په قېدخانه کښې د مسيح د کارونو نه خبر شو، نو خپل يو څو مريدان يې ورولېږل چې د عيسىٰ نه دا تپوس وکړى چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22347, 'Matthew 11:3', 'Matthew', 11, 3, '&nbsp;”ولې هغه راتلونکے تۀ يې څۀ؟ او يا کۀ نه، مونږ د بل چا اِنتظار وکړو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22348, 'Matthew 11:4', 'Matthew', 11, 4, '&nbsp;عيسىٰ ورله جواب ورکړو، ”لاړ شئ، څۀ چې تاسو اورئ او ګورئ، هغه يحيىٰ ته ووايئ', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22349, 'Matthew 11:5', 'Matthew', 11, 5, '&nbsp;چې ړاندۀ بينا کيږى، شل ګرځى، جذاميان پاکيږى، کاڼۀ اورى او مړى بيا ژوندى کيږى او غريبانان ښۀ زېرے اورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22350, 'Matthew 11:6', 'Matthew', 11, 6, '&nbsp;او بختور دى هغه څوک چې ما نۀ ازاروى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22351, 'Matthew 11:7', 'Matthew', 11, 7, '&nbsp;څۀ وخت چې د يحيىٰ مريدان واپس رُخصت شول نو عيسىٰ خلقو ته د يحيىٰ په حقله دا وفرمائيل، ”تاسو د څۀ ليدلو دپاره بيابان ته تلى وئ؟ يوه لوخه چې باد خوځوله څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22352, 'Matthew 11:8', 'Matthew', 11, 8, '&nbsp;نو بيا تاسو د څۀ ليدو له وتلى وئ؟ يو کس چې ښکلې او نرمې جامې يې اچولې وې؟ ګورئ، هغه څوک چې نرمې جامې اچوى هغه په محلونو کښې اوسيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22353, 'Matthew 11:9', 'Matthew', 11, 9, '&nbsp;نو بيا تاسو بهر د څۀ ليدو له وتلى وئ؟ د يو نبى ليدلو ته؟ آو، رښتيا چې د يو نبى نه هم څۀ ډېر لوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22354, 'Matthew 11:10', 'Matthew', 11, 10, '&nbsp;دا هغه څوک دے چې د چا په حقله چې ليکلے شوى دى چې، ”ګوره، زۀ خپل پېغمبر ستا نه وړاندې لېږم چې ستا مخې ته لاره تياره کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22355, 'Matthew 11:11', 'Matthew', 11, 11, '&nbsp;زۀ تاسو ته رښتيا وايم د زمکې په مخ بل څوک د يحيىٰ بپتسمه ورکونکى نه لوئ نشته خو بيا هم د خُدائ پاک په بادشاهۍ کښې د ټولو نه کمزورے کس د هغۀ نه لوئ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22356, 'Matthew 11:12', 'Matthew', 11, 12, '&nbsp;د بپتسمه ورکونکى يحيىٰ د راتلو د ورځو نه پس لا تر اوسه د آسمان په بادشاهۍ زور کولے شى او زورَور يې په زور رانيسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22357, 'Matthew 11:13', 'Matthew', 11, 13, '&nbsp;ځکه چې د يحيىٰ د راتلو نه وړاندې ټولو نبيانو او د موسىٰ شريعت د دې وخت انتظار کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22358, 'Matthew 11:14', 'Matthew', 11, 14, '&nbsp;نو کۀ تاسو غواړئ چې هغه ومنئ نو هغه په خپله الياس دے څوک چې راتلونکے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22359, 'Matthew 11:15', 'Matthew', 11, 15, '&nbsp;څوک چې غوږونه لرى نو هغه دې واورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22360, 'Matthew 11:16', 'Matthew', 11, 16, '&nbsp;زۀ د دې پيړۍ مِثال څنګه درکړم؟ دوئ لکه په بازار کښې د ناستو ماشومانو په شان دى چې يو بل ته نعرې وهى چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22361, 'Matthew 11:17', 'Matthew', 11, 17, '&nbsp;”مونږ درته شپيلۍ وغږوله او تاسو ګډ نۀ شوئ، مونږ درته ځان ووهلو او وير مو وکړو خو تاسو ونۀ ژړل.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
